function getCustomData(db, onyID, data) {
    var sql = "SELECT * FROM `marin_customdata` WHERE `id` = '" + onyID + "' LIMIT 1;";
    var ret = db.select(sql);
    if (ret.length <= 0) {
        return null;
    } else {
        var split = [];
        split = ret[0].get('customData').split(";");
        for (var n in split) {
            var splitB = split[n].split("=");
            if (splitB.length != 2 || !splitB[0].equals(data)) continue;
            return splitB[1];
        }
        return null;
    }
}

function setCustomData(stage, db, onyID, key, value) {
    var Equip = stage.getItemBySlot(1, 1);
    var sql = "SELECT * FROM `marin_customdata` WHERE `id` = '" + onyID + "' LIMIT 1;";
    var ret = db.select(sql);
    if (ret.length <= 0) {
        db.insert("INSERT INTO `marin_customdata`(`id`, `itemid`, `customData`) VALUES (" + onyID + ", " + Equip['itemId'] + ", '" + key + "=" + value + "');");
        return;
    }
    if (ret[0].get('customData').indexOf(key) <= -1) {
        var info = ret[0].get('customData');
        info = info + ";" + key + "=" + value;
        db.update("UPDATE `marin_customdata` SET `customData` = '" + info + "' WHERE `id` = " + onyID + ";")
        return;
    }
    var split = [];
    split = ret[0].get('customData').split(";");
    var changed = false;
    var newsplit = new StringBuilder();
    for (var n in split) {
        var splitB = split[n].split("=");
        if (splitB.length != 2) continue;
        if (splitB[0].equals(key)) {
            newsplit.append(key);
            newsplit.append("=");
            newsplit.append(value);
            changed = true;
        } else {
            newsplit.append(split[n]);
        }
        newsplit.append(";");
    }
    if (!changed) {
        newsplit.append(key);
        newsplit.append("=");
        newsplit.append(value);
    }
    var ret = db.select(sql);
    var info = ret[0].get('customData');
    var newInfo = key + "=" + value;
    var beforeStat = info.substring(0, info.indexOf(key));
    var from = info.indexOf(";", info.indexOf(key) + key.length);
    var afterStat = from == -1 ? "" : info.substring(from + 1);
    var write = String(beforeStat) + String(newInfo) + (afterStat.length != 0 ? ";" + afterStat : "");
    db.update("UPDATE `marin_customdata` SET `customData` = '" + write + "' WHERE `id` = " + onyID + ";")
}

function StringBuilder() {
    this.arr = new Array();
    this.append = function (str) {
        this.arr.push(str);
    }
    this.tostring = function () {
        return this.arr.join('');
    }
}

function getEquipCareer(equipId, marin) {
    for (var careerId in marin) {
        var careerEquipLists = marin[careerId];
        for (var equipList of careerEquipLists) {
            if (equipList.includes(equipId)) {
                return {careerId: careerId, equipList: equipList};
            }
        }
    }
    return null;
}

function getItemType(itemid) {
    var type = Math.floor(itemid / 10000);
    switch (type) {
        case 100:
            return 0; //帽子
        case 104:
            return 1; //上衣
        case 105:
            return 2; //套裝
        case 106:
            return 3; //褲裙
        case 107:
            return 4; //鞋子
        case 108:
            return 5; //手套
        case 110:
            return 6; //披風
        case 115:
            return 8; //護肩
        case 111:
            return 9; //ring
        case 113:
            return 10; //腰帶
        case 116:
            return 11;//口袋物品
        default:
            if (type == 120) return -1; //銀河
            if (type == 135) return -1; //副手
            var type = Math.floor(type / 10);
            if (type == 12 || type == 13 || type == 14 || type == 15 || type == 17) {
                return 7; //武器
            }
            return -1;
    }
}

