function getRandomIdByProbability(pro) {
    let totalProbability = Object.values(pro).reduce((acc, val) => acc + val, 0);
    let randomNum = Math.random() * totalProbability;
    let cumulativeProbability = 0;
    let idsWithSameProb = [];
    for (let id in pro) {
        cumulativeProbability += pro[id];
        if (randomNum <= cumulativeProbability) {
            idsWithSameProb.push(id);
        }
    }
    if (idsWithSameProb.length > 1) {
        return idsWithSameProb[Math.floor(Math.random() * idsWithSameProb.length)];
    } else {
        return idsWithSameProb[0];
    }
}
